const palavrasDistintivas = (nome, cidade = '') => {
  const daCidade = new Set(norm(cidade).split(' '));
  return norm(nome).split(' ')
    .filter((w) => w.length >= 3 && !GENERICAS.has(w) && !daCidade.has(w) && !['de', 'da', 'do', 'das', 'dos', 'dra', 'dr', 'the'].includes(w));
