  const u = email.split('@')[0].replace(/[^a-z0-9]/g, '');
  const ds = palavrasDistintivas(nome, cidade);
  const achadas = ds.filter((w) => u.includes(w));
  if (!ds.length || achadas.length < Math.min(2, ds.length)) return false;
