  const semConectivos = palavras.filter((w) => !['de', 'da', 'do', 'das', 'dos', 'e', 'dra', 'dr'].includes(w));
  const slugs = [...new Set([palavras.join(''), semConectivos.join('')])];
  const out = [];
  for (const s of slugs) out.push(`${s}@gmail.com`, `contato.${s}@gmail.com`);
